import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"2、【坤】 坤下坤上","description":"溫公易說 - 2、【坤】 坤下坤上","frontmatter":{"title":"2、【坤】 坤下坤上","description":"溫公易說 - 2、【坤】 坤下坤上"},"headers":[],"relativePath":"classics/wengong/003.md","filePath":"classics/wengong/003.md"}'),l={name:"classics/wengong/003.md"};function n(t,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_2、【坤】-坤下坤上" tabindex="-1">2、【坤】 坤下坤上 <a class="header-anchor" href="#_2、【坤】-坤下坤上" aria-label="Permalink to “2、【坤】 坤下坤上”">​</a></h1><h3 id="彖曰-至哉-坤元-萬物資生-乃順承天。坤厚載物-德合無疆。含光-大品物咸亨。牝馬地類-行地無疆。柔順利貞-君子攸行。先迷失道-後順得常。西南得朋-乃與類行。東北喪朋-乃終有慶。安貞之吉-應地無疆。" tabindex="-1">彖曰：至哉，坤元！萬物資生，乃順承天。坤厚載物，德合無疆。含光，大品物咸亨。牝馬地類，行地無疆。柔順利貞，君子攸行。先迷失道，後順得常。西南得朋，乃與類行。東北喪朋，乃終有慶。安貞之吉，應地無疆。 <a class="header-anchor" href="#彖曰-至哉-坤元-萬物資生-乃順承天。坤厚載物-德合無疆。含光-大品物咸亨。牝馬地類-行地無疆。柔順利貞-君子攸行。先迷失道-後順得常。西南得朋-乃與類行。東北喪朋-乃終有慶。安貞之吉-應地無疆。" aria-label="Permalink to “彖曰：至哉，坤元！萬物資生，乃順承天。坤厚載物，德合無疆。含光，大品物咸亨。牝馬地類，行地無疆。柔順利貞，君子攸行。先迷失道，後順得常。西南得朋，乃與類行。東北喪朋，乃終有慶。安貞之吉，應地無疆。”">​</a></h3><h3 id="象曰-地勢坤-君子以厚德載物。" tabindex="-1">象曰：地勢坤，君子以厚德載物。 <a class="header-anchor" href="#象曰-地勢坤-君子以厚德載物。" aria-label="Permalink to “象曰：地勢坤，君子以厚德載物。”">​</a></h3><p>幹之象曰：自強不息。坤之象曰：厚德載物。何也？曰：強者，勉之謂也；載者，安濟之謂也。君子自強，法天；厚德，法地。德不厚，則物不得而濟也。是故，自強不息，則道無不臻；厚德而載，則物無不濟。夫乾坤者，易之門戶也。二象者，道德之關樞也。</p><h3 id="初六-履霜-堅冰至。-象曰-履霜-堅冰至-陰始凝也。馴致其道-至堅冰也。" tabindex="-1">初六：履霜，堅冰至。 象曰：履霜，堅冰至，陰始凝也。馴致其道，至堅冰也。 <a class="header-anchor" href="#初六-履霜-堅冰至。-象曰-履霜-堅冰至-陰始凝也。馴致其道-至堅冰也。" aria-label="Permalink to “初六：履霜，堅冰至。 象曰：履霜，堅冰至，陰始凝也。馴致其道，至堅冰也。”">​</a></h3><p>初六者，陰之始也，於律為林鐘，於歷為建未之月，陽氣方盛，陰生而物未之知也。是故君子謹之。其曰履霜堅冰至，霜者寒之先也，冰者寒之盛也。君子見微而知彰，原始而知終，攘惡於未芽，杜禍於未萌，是以身禔而國家乂寜也。</p><h3 id="六二-直方大-不習無不利。-象曰-六二之動-直以方也。不習無不利-地道光也。" tabindex="-1">六二：直方大，不習無不利。 象曰：六二之動，直以方也。不習無不利，地道光也。 <a class="header-anchor" href="#六二-直方大-不習無不利。-象曰-六二之動-直以方也。不習無不利-地道光也。" aria-label="Permalink to “六二：直方大，不習無不利。 象曰：六二之動，直以方也。不習無不利，地道光也。”">​</a></h3><p>六二者，於律為南呂，於歷為建酉之月，草木黃落，暑去而寒至也。其曰直方大何？直方而大地之徳也。六二何為擅地之徳？坤之主也。六二何為坤之主？夫陰陽雖殊，皆主中正者也。故幹九五，陽之主也；坤六二，陰之主也。地之得其為直方大者何？直者言其氣，方者言其形，大者兼形與氣而言之也。</p><h3 id="六三-含章可貞-或從王事-無成有終。-象曰-含章可貞-以時發也。或從王事-知光大也。" tabindex="-1">六三：含章可貞，或從王事，無成有終。 象曰：含章可貞，以時發也。或從王事，知光大也。 <a class="header-anchor" href="#六三-含章可貞-或從王事-無成有終。-象曰-含章可貞-以時發也。或從王事-知光大也。" aria-label="Permalink to “六三：含章可貞，或從王事，無成有終。 象曰：含章可貞，以時發也。或從王事，知光大也。”">​</a></h3><p>乾坤之爻得位未必告失位未必兇，其故何也？曰陽非陰則不成，陰非陽則不生。陰陽之道表裡相承，陰勝則消，陽勝則亢。是故乾坤以陰居陽，以陽居陰，不皆為咎也。幹之九三以陽居陽而不中，故曰夕惕若厲無咎。坤之六四以陰居陰而不中，故曰括囊無咎無譽，皆剛柔太過，故須畏慎而後免咎也。然未失其正，故不兇也。九五六二居中履正，其徳最羙。九二六五不失其中，徳羙次之。九三六四不失其正，雖危無疑。九四六三雖無中正之徳，九四以陽處下，剛克而沈潛者也，故曰在淵無咎。六三以陰處上，柔克而髙明者也，故曰含章可貞。六三者，於律為應鐘，於歷為建亥之月，百榖斂藏，萬物備成，陰功小終，體執乎柔而志存乎剛，故曰含章。柔不泥於下，剛不疑乎上，故曰可貞。王者尊之極也，為臣之榮從王役，不敢專成，下之職也，承事之終，臣之力也。物以陽生，得陰而成，令由君出，得臣而行，故陽而不陰則萬物傷矣，君而不臣則百職曠矣。陰陽同功，君臣同體，天之經也，人之紀也。虞書曰：予欲左右有民，汝翼；予欲宣力四方，汝為。此之謂也。</p><h3 id="六四-括囊-無咎無譽。-象曰-括囊-無咎慎不害也。" tabindex="-1">六四：括囊，無咎無譽。 象曰：括囊，無咎慎不害也。 <a class="header-anchor" href="#六四-括囊-無咎無譽。-象曰-括囊-無咎慎不害也。" aria-label="Permalink to “六四：括囊，無咎無譽。 象曰：括囊，無咎慎不害也。”">​</a></h3><p>六四者，於律為大呂，於歷為建醜之月，曰窮於次月，窮於紀天吟地閉，萬物伏死，陰氣大盛，陽將更始，履卑體順，以陰居陰處，不得中而潛伏乎其深，是以幽晦否塞而不通，雖無咎亦無譽也。</p><h3 id="六五-黃裳-元吉。-象曰-黃裳-元吉-文在中也。" tabindex="-1">六五：黃裳，元吉。 象曰：黃裳，元吉，文在中也。 <a class="header-anchor" href="#六五-黃裳-元吉。-象曰-黃裳-元吉-文在中也。" aria-label="Permalink to “六五：黃裳，元吉。 象曰：黃裳，元吉，文在中也。”">​</a></h3><p>六五者，於律為夾鍾，於歷為建帽之月，天地始闢，和氣融明，莩甲發散，庶物滋榮，體柔而志剛，乘陰而佐陽，中羙能黃，上羙則元，下羙則裳，是以吉也。</p><h3 id="上六-龍戰於野-其血玄黃。-象曰-龍戰於野-其道窮也。" tabindex="-1">上六：龍戰於野，其血玄黃。 象曰：龍戰於野，其道窮也。 <a class="header-anchor" href="#上六-龍戰於野-其血玄黃。-象曰-龍戰於野-其道窮也。" aria-label="Permalink to “上六：龍戰於野，其血玄黃。 象曰：龍戰於野，其道窮也。”">​</a></h3><p>上六者，陰之窮也，於律為仲呂，於歷為建巳之月，純陰用事，陽道已窮，冒進不已，不能守中，是以戰也。夫下不能自重，重之者上也；臣不能自大，大之者君也。重而不已，上必危；大而不已，君必虧。既危且虧，能無戰乎？故君子執臣之樞，守臣之機，謹其樞，固其機，禍無從來。樞機之失，儓僕為災；雖得而勝之，猶有傷也。故曰其血黃。文言曰：臣弒其君，子弒其父，非一朝一夕之故，其所由來者漸矣，由辨之不早辨也。嗚呼，聖人之戒為人上者如此其深乎！</p><h3 id="用六-利永貞。-象曰-用六-永貞以大終也。" tabindex="-1">用六：利永貞。 象曰：用六，永貞以大終也。 <a class="header-anchor" href="#用六-利永貞。-象曰-用六-永貞以大終也。" aria-label="Permalink to “用六：利永貞。 象曰：用六，永貞以大終也。”">​</a></h3><p>文言曰：</p><h3 id="坤至柔而動也剛-至靜而德方。後得主而有常-含萬物而化光。坤道其順乎-承天而時行。積善之家-必有餘慶-積不善之家-必有餘殃。臣弒其君-子弒其父-非一朝一夕之故-其所由來者漸矣。由辨之不早辨也。《易》曰-履霜堅冰至-蓋言順也。直其正也-方其義也。君子敬以直內-義以方外。敬義立而德不孤-直方大不習-無不利-則不疑其所行也。" tabindex="-1">坤至柔而動也剛，至靜而德方。後得主而有常，含萬物而化光。坤道其順乎？承天而時行。積善之家，必有餘慶；積不善之家，必有餘殃。臣弒其君，子弒其父，非一朝一夕之故，其所由來者漸矣。由辨之不早辨也。《易》曰：履霜堅冰至，蓋言順也。直其正也，方其義也。君子敬以直內，義以方外。敬義立而德不孤，直方大不習，無不利，則不疑其所行也。 <a class="header-anchor" href="#坤至柔而動也剛-至靜而德方。後得主而有常-含萬物而化光。坤道其順乎-承天而時行。積善之家-必有餘慶-積不善之家-必有餘殃。臣弒其君-子弒其父-非一朝一夕之故-其所由來者漸矣。由辨之不早辨也。《易》曰-履霜堅冰至-蓋言順也。直其正也-方其義也。君子敬以直內-義以方外。敬義立而德不孤-直方大不習-無不利-則不疑其所行也。" aria-label="Permalink to “坤至柔而動也剛，至靜而德方。後得主而有常，含萬物而化光。坤道其順乎？承天而時行。積善之家，必有餘慶；積不善之家，必有餘殃。臣弒其君，子弒其父，非一朝一夕之故，其所由來者漸矣。由辨之不早辨也。《易》曰：履霜堅冰至，蓋言順也。直其正也，方其義也。君子敬以直內，義以方外。敬義立而德不孤，直方大不習，無不利，則不疑其所行也。”">​</a></h3><p>註釋：君子法地之直方，則敬以直內，義以方外。敬義立而德不孤，則大也。何謂敬以直內，義以方外？敬則所受不陷於敗也，義則所適不失其宜也。直且方者，守諸己而無待於外也。君子居則不陷於敗，動則不爽其宜。施於身而身正，施於國而國治。夫又何習而何不利焉，可以斷然無疑矣。</p><h3 id="陰雖有美-含之以從王事-弗敢成也。地道也-妻道也-臣道也。地道無成而代有終也。天地變化-草木蕃-天地閉-賢人隱。《易》曰-括囊無咎無譽-蓋言謹也。君子黃中通理-正位居體-美在其中而暢於四肢-發於事業-美之至也。陰疑於陽-必戰-為其嫌於無陽也-故稱龍焉。猶未離其類也-故稱血焉。夫黃者-天地之雜也-天而地黃。" tabindex="-1">陰雖有美，含之以從王事，弗敢成也。地道也，妻道也，臣道也。地道無成而代有終也。天地變化，草木蕃；天地閉，賢人隱。《易》曰：括囊無咎無譽，蓋言謹也。君子黃中通理，正位居體，美在其中而暢於四肢，發於事業，美之至也。陰疑於陽，必戰，為其嫌於無陽也，故稱龍焉。猶未離其類也，故稱血焉。夫黃者，天地之雜也，天而地黃。 <a class="header-anchor" href="#陰雖有美-含之以從王事-弗敢成也。地道也-妻道也-臣道也。地道無成而代有終也。天地變化-草木蕃-天地閉-賢人隱。《易》曰-括囊無咎無譽-蓋言謹也。君子黃中通理-正位居體-美在其中而暢於四肢-發於事業-美之至也。陰疑於陽-必戰-為其嫌於無陽也-故稱龍焉。猶未離其類也-故稱血焉。夫黃者-天地之雜也-天而地黃。" aria-label="Permalink to “陰雖有美，含之以從王事，弗敢成也。地道也，妻道也，臣道也。地道無成而代有終也。天地變化，草木蕃；天地閉，賢人隱。《易》曰：括囊無咎無譽，蓋言謹也。君子黃中通理，正位居體，美在其中而暢於四肢，發於事業，美之至也。陰疑於陽，必戰，為其嫌於無陽也，故稱龍焉。猶未離其類也，故稱血焉。夫黃者，天地之雜也，天而地黃。”">​</a></h3>',21)])])}const _=e(l,[["render",n]]);export{b as __pageData,_ as default};
